            var _wmActiveItemClosed = false;
            function wmPopulateStatus(type, currentVal, selId) {
                var opts = type === 'appt' ? WM_STATUS_APPT : WM_STATUS_TASK;
                /* hidden <select> sync */
                var sel = wmG(selId || 'ld2AwStatus');
                var prefix = (selId === 'ld2VwStatus') ? 'ld2Vw' : 'ld2Aw';
                var lower = (currentVal || '').toLowerCase();
                var matched = null;
                for (var i = 0; i < opts.length; i++) {
                    if (opts[i].value.toLowerCase() === lower) { matched = opts[i]; break; }
                }
                if (!matched) matched = opts[0];
                /* sync hidden select */
                if (sel) {
                    sel.innerHTML = opts.map(function(o) { return '<option value="' + o.value + '">' + o.label + '</option>'; }).join('');
                    sel.value = matched.value;
                }
                /* render custom dropdown */
                var btnEl = wmG(prefix + 'StatusBtn');
                var listEl = wmG(prefix + 'StatusList');
                if (!btnEl || !listEl) return;
                btnEl.setAttribute('data-val', matched.value);
                btnEl.firstChild ? (btnEl.firstChild.textContent = matched.label) : (btnEl.textContent = matched.label);
                listEl.innerHTML = opts.map(function(o) {
                    var isActive = o.value === matched.value;
                    return '<div class="wm-sd-item' + (isActive ? ' active' : '') + '" data-val="' + o.value + '" onclick="window.wmSdSelect(\'' + prefix + '\',this)">'
                        + o.label
                        + '<i class="fas fa-check wm-sd-chk"></i>'
                        + '</div>';
                }).join('');
            }

