                var sdLeadClosedBlock = (wrapId === 'ld2AwStatusWrap' && !_wmEditRef)
                    && typeof LD2_LEAD_CLOSED !== 'undefined' && LD2_LEAD_CLOSED;
                if (sdLeadClosedBlock || _wmActiveItemClosed) return;
