                if (vwStatusBtn) vwStatusBtn.classList.toggle('wm-sd-disabled', _wmActiveItemClosed || vwNoEditRole);
                /* ★ 07/09: ปุ่มดินสอ (แก้ไข) — ปิดเมื่อนัดหมาย/งานปิดจบแล้วเช่นกัน กันเปิด modal แก้ไขรายการที่จบแล้ว */
                var vwEditBtn = wmG('ld2VwEditBtn');
